Contact2Zip END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('Contact2Country'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @Contact2Country END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('Contact2PhoneOffice'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @Contact2PhoneOffice END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('Contact2Fax'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @Contact2Fax END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('Contact2EmailAddress'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @Contact2EmailAddress END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('Contact1PhoneMobile'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @Contact1PhoneMobile END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('Contact2PhoneMobile'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @Contact2PhoneMobile END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('EnablePasswordHint'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @EnablePasswordHint END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('EnablePasswordReset'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @EnablePasswordReset END),@MeterReconciliationToleranceIsPercent,(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('MeterReconciliationReportName'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @MeterReconciliationReportName END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('TranslatedHelpURL'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @TranslatedHelpURL END),@AllowUseOfSpecialChars,@EnablePeriodicSyncFlag,@PeriodicSyncIntervalMinutes,@DisableSyncTransferFlag,(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('CardInTimeout'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @CardInTimeout END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('TerminalControlNumber'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @TerminalControlNumber END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('BlockCloseOnUnpostedBOL'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @BlockCloseOnUnpostedBOL END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('InhibitLoadRackCardIns'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @InhibitLoadRackCardIns END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('PromptForThirdTrailer'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @PromptForThirdTrailer END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('PromptForTransactionCompletion'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @PromptForTransactionCompletion END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('InhibitCustomerConfirmationPrompt'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @InhibitCustomerConfirmationPrompt END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('EnableBOLPDFArchiving'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @EnableBOLPDFArchiving END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('BOLPDFArchivingPath'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @BOLPDFArchivingPath END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('RequireTrailerScully'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @RequireTrailerScully END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('Latitude'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @Latitude END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('Longitude'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @Longitude END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('Zoom'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @Zoom END),@GlobalAccessToPersonnel,@GlobalAccessToEquipment,@Enterprise,@OperateTabGroups,(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('EnterpriseUserId'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @EnterpriseUserId END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('EnterprisePassword'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @EnterprisePassword END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('EnterpriseSite'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @EnterpriseSite END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ActiveDirectorySiteGroupGuid'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @ActiveDirectorySiteGroupGuid END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ServerEndPoint'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @ServerEndPoint END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('SecurityMode'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @SecurityMode END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('SecurityPolicy'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @SecurityPolicy END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('MessageEncoding'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @MessageEncoding END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('UserIdentityMethod'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @UserIdentityMethod END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('UserId'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @UserId END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('UserPassword'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @UserPassword END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('UserCertificatePath'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @UserCertificatePath END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('MaximumDaysToRetainArchive'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @MaximumDaysToRetainArchive END),@EnforceSalesOrderLimit,(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('LeakDetectionQuietSamples'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @LeakDetectionQuietSamples END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('LeakDetectionQuietTime'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @LeakDetectionQuietTime END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('LeakDetectionQuietTimeFactor'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @LeakDetectionQuietTimeFactor END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('LeakDetectionUseMinWait'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @LeakDetectionUseMinWait END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('LeakDetectionReport'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @LeakDetectionReport END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('LeakDetectionPrinter'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @LeakDetectionPrinter END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('EnableAutomaticMovementTicketPrinting'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @EnableAutomaticMovementTicketPrinting END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('MovementTicketReport'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @MovementTicketReport END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('MovementTicketPrinter'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @MovementTicketPrinter END),@MaxOperateTabsAllowed,(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('CloseoutTime'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @CloseoutTime END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('PointGroupFileExportDirectory'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @PointGroupFileExportDirectory END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('PointGroupDefaultFileName'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @PointGroupDefaultFileName END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('EnableMovementTicketPDFArchiving'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @EnableMovementTicketPDFArchiving END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('MovementTicketFileExportDirectory'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @MovementTicketFileExportDirectory END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('MovementTicketExportFileName'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @MovementTicketExportFileName END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('MovementNumber'), @sync_supported_columns_tblSites)) WHEN 0 THEN NULL ELSE @MovementNumber END))
            ;
         SET @sync_row_count = @@rowcount;
    END
    ELSE
    BEGIN
          SET @sync_row_count = 1
    END

    -- If we updated / inserted a record here, go ahead and remove any pending conflict records associated with this ID because this record should contain the most recent data.
    IF (@sync_row_count > 0)
    BEGIN
        SET NOCOUNT ON
        IF EXISTS (SELECT 1 FROM [sync].[tblSyncRecordConflict] WHERE RecordKey = CONVERT(nvarchar(512), @SiteGuid) AND SyncConflictResolutionStatusIndex IN (0,3))
        BEGIN
            DELETE FROM [sync].[tblSyncRecordConflictToSyncSessionScopeLog] WHERE SyncRecordConflictGuid IN (SELECT SyncRecordConflictGuid FROM [sync].[tblSyncRecordConflict] WHERE RecordKey = CONVERT(nvarchar(512), @SiteGuid))
            DELETE FROM [sync].[tblSyncRecordConflict] WHERE RecordKey = CONVERT(nvarchar(512), @SiteGuid)
        END
        SET NOCOUNT OFF
    END

    -- One issue with the MERGE approach is that we don't know if the @@rowcount is zero because of a true conflict now or if it was simply because
    -- the CreatedDate and UpdatedDate qualifiers were not met (in which case we want to simply throw away the update)
    -- In order to determine what took place, we're going to need to perform a query if @@rowcount = 0 to see if it was caused by the additional qualifiers.
    --
    IF (@sync_row_count = 0)
    BEGIN
        IF EXISTS (SELECT 1 FROM [dbo].[tblSites] WHERE SiteGuid = @SiteGuid AND (CreatedDate >= @CreatedDate OR UpdatedDate >= @UpdatedDate))
            SET @sync_row_count = 1;
    END
    
    SET @minValidVersion = 0;   -- This is used to detect Change Tracking cleanup
                                -- If we support this, we should add a column to SynchronizationTable
                                -- that records the MinValidVersion after change tracking information for
                                -- a table gets cleaned up.  I don't think this will be necessary.
    
    IF @minValidVersion > @sync_last_received_anchor 
        RAISERROR(N'(SU)Time between synchronization has exceeded the maximum amount of time for table ''%s'' (MIN: %I64d, LAST: %I64d).  To avoid data corruption and old data, the client must reinitialize its local database with a current refresh from the server.', 16, 3, @sync_table_name, @minValidVersion, @sync_last_received_anchor)
END
